using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            for (int i = 0; i < SceneManager.sceneCount; i++)
                if (SceneManager.GetSceneAt(i).isDirty)
                    throw new System.Exception("Unsaved scene: " + SceneManager.GetSceneAt(i).name);
            EditorSceneManager.OpenScene("Assets/CampusSim/Scenes/PC_Bootstrap.unity");
            result.Log("Bootstrap ready");
        }
    }
}
